<form method="post" action="{{ route('checkout.store') }}" class="grid gap-6 xl:grid-cols-[1fr_360px]">@csrf<input type="hidden" name="idempotency_key" :value="key"><div class="space-y-6"><div class="card p-6"><div class="flex items-center justify-between"><div><div class="text-xs font-bold uppercase tracking-[.15em] text-[#698773]">01 / Keranjang</div><h2 class="mt-2 text-lg font-semibold">Item pembelian</h2></div><button type="button" @click="items.push({name:'',quantity:1,unit_price:0,eligible:true})" class="btn btn-light">+ Tambah item</button></div><div class="mt-6 space-y-3"><template x-for="(item,index) in items" :key="index"><div class="grid grid-cols-[1fr_76px_110px_32px] gap-2"><input class="field" :name="`items[${index}][name]`" x-model="item.name" placeholder="Nama produk" required><input class="field" type="number" min="1" :name="`items[${index}][quantity]`" x-model.number="item.quantity" required><input class="field" type="number" min="0" :name="`items[${index}][unit_price]`" x-model.number="item.unit_price" placeholder="Harga" required><button type="button" @click="if(items.length>1)items.splice(index,1)" class="text-xl text-[#9aada0]">×</button><label class="col-span-4 flex items-center gap-2 pl-1 text-xs text-[#718075]"><input type="checkbox" value="1" :name="`items[${index}][eligible]`" x-model="item.eligible"> Menghasilkan poin</label></div></template></div></div><div class="card p-6"><div class="text-xs font-bold uppercase tracking-[.15em] text-[#698773]">02 / Pelanggan</div><h2 class="mt-2 text-lg font-semibold">Identitas member</h2><div class="mt-5"><label class="label">Pilih member</label><select class="field" name="member_id" x-model="memberId"><option value="">Tanpa member</option><template x-for="member in members" :key="member.id"><option :value="member.id" x-text="`${member.name} · ${member.phone}`"></option></template></select><p class="mt-2 text-xs text-[#859187]">Member baru dapat ditambahkan dari halaman Member.</p></div><div x-show="selected" class="mt-4 rounded-xl bg-[#edf5e9] p-4 text-sm text-[#315e3d]"><strong x-text="selected?.point_balance ?? 0"></strong> poin tersedia <span x-show="selected?.point_debt">· utang <span x-text="selected?.point_debt"></span> poin</span></div></div><div class="card p-6"><div class="text-xs font-bold uppercase tracking-[.15em] text-[#698773]">03 / Pembayaran</div><h2 class="mt-2 text-lg font-semibold">Rincian pembayaran</h2><div class="mt-5 grid gap-4 sm:grid-cols-2"><div><label class="label">Diskon transaksi (Rp)</label><input class="field" type="number" name="discount" min="0" x-model.number="discount" required></div><div><label class="label">Tukar poin</label><input class="field" type="number" name="redeem_points" min="0" x-model.number="redeem" :disabled="!selected || !rule" required></div><div><label class="label">Outlet</label><select class="field" name="outlet_id" required>@foreach($outlets as $outlet)<option value="{{ $outlet->id }}">{{ $outlet->name }}</option>@endforeach</select></div><div><label class="label">Metode pembayaran</label><select class="field" name="payment_method"><option value="cash">Tunai</option><option value="qris">QRIS</option><option value="transfer">Transfer</option><option value="card">Kartu</option></select></div></div></div></div>
<div><div class="card sticky top-5 overflow-hidden"><div class="bg-[#193b2b] p-6 text-white"><div class="text-xs font-bold uppercase tracking-[.17em] text-[#a9c8ad]">Ringkasan pembayaran</div><div class="mt-5 text-4xl font-semibold" x-text="rupiah(total)"></div><div class="mt-2 text-xs text-[#afc6b2]">Jumlah yang perlu dibayar</div></div><div class="space-y-4 p-6 text-sm"><div class="flex justify-between"><span class="text-[#728076]">Subtotal</span><span x-text="rupiah(subtotal)"></span></div><div class="flex justify-between"><span class="text-[#728076]">Diskon</span><span x-text="'- '+rupiah(discount)"></span></div><div class="flex justify-between"><span class="text-[#728076]">Potongan poin</span><span x-text="'- '+rupiah(redeemValue)"></span></div><div class="border-t pt-4"><div class="flex justify-between"><span>Perkiraan poin baru</span><strong class="text-[#2b7a4b]" x-text="'+ '+earn+' poin'"></strong></div><p class="mt-2 text-xs leading-5 text-[#89978a]">Poin dihitung ulang saat pembayaran dicatat.</p></div><template x-if="problem"><p class="rounded-lg bg-red-50 p-3 text-xs text-red-700" x-text="problem"></p></template><button class="btn btn-primary w-full" :disabled="!!problem || total < 0" :class="{'opacity-50': !!problem || total < 0}">Catat pembayaran →</button><p class="text-center text-xs leading-5 text-[#8b978d]">Pastikan pembayaran sudah diterima sebelum mencatat transaksi.</p></div></div></div></form></div>
<script>function checkoutPage(members, rule){return {members,rule,key:crypto.randomUUID(),items:[{name:'',quantity:1,unit_price:0,eligible:true}],memberId:'',discount:0,redeem:0,get selected(){return this.members.find(x=>String(x.id)===String(this.memberId))},get subtotal(){return this.items.reduce((a,x)=>a+(Number(x.quantity)||0)*(Number(x.unit_price)||0),0)},get eligible(){return this.items.reduce((a,x)=>a+(x.eligible?(Number(x.quantity)||0)*(Number(x.unit_price)||0):0),0)},get redeemValue(){return (Number(this.redeem)||0)*(this.rule?.redeem_value||0)},get total(){return this.subtotal-(Number(this.discount)||0)-this.redeemValue},get earn(){let base=Math.max(0,this.eligible-(Number(this.discount)||0)-this.redeemValue);return this.selected&&this.rule&&base>=this.rule.minimum_spend?Math.floor(base/this.rule.earn_step)*this.rule.earn_points:0},get problem(){if((Number(this.discount)||0)>this.subtotal)return 'Diskon melebihi subtotal.';if(!this.redeem)return '';if(!this.selected||!this.rule)return 'Pilih member dan aktifkan aturan poin.';if(this.redeem<this.rule.minimum_redeem)return `Minimal ${this.rule.minimum_redeem} poin.`;if(this.redeem>this.selected.point_balance)return 'Saldo poin tidak cukup.';if(this.redeemValue>Math.floor(Math.max(0,this.eligible-this.discount)*this.rule.maximum_redeem_percent/100))return 'Melebihi batas penukaran transaksi.';return ''},rupiah(n){return 'Rp'+Math.max(0,Number(n)||0).toLocaleString('id-ID')}}}</script>
